1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - next generation", () => {
5	  it("should return an empty grid for an empty grid — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should kill a single lone cell (0 neighbors) — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("Rule 1 Underpopulation: should kill both cells that have 1 neighbor each — [(0,1), (1,1)] → []", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 1],
15	        [1, 1],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("Rule 2 Survival: should keep a live cell with 3 live neighbors alive — center (1,1) survives", () => {
20	    // Gen 0: ### on the top row, plus the live centre cell (1,1).
21	    // (1,1) is live and has exactly 3 live neighbours: (0,0), (1,0), (2,0).
22	    const result = nextGeneration([
23	      [0, 0],
24	      [1, 0],
25	      [2, 0],
26	      [1, 1],
27	    ]);
28	
29	    expect(result).toContainEqual([1, 1]);
30	  });
31	  it("Rule 3 Overpopulation: should kill a live cell with 4 live neighbors — center (1,1) dies", () => {
32	    // Gen 0: the live centre (1,1) surrounded by the four corners of its
33	    // 3x3 box, giving it exactly 4 live neighbours.
34	    const result = nextGeneration([
35	      [0, 0],
36	      [2, 0],
37	      [1, 1],
38	      [0, 2],
39	      [2, 2],
40	    ]);
41	
42	    expect(result).not.toContainEqual([1, 1]);
43	  });
